local a={}function a.getTransfers(b,c)local d=b:getAllByType("TRANSFER")local e={}for f,g in ipairs(d)do local h,i=table.unpack(g[3])table.insert(e,{text="Transfer from '"..h.."' to '"..i.."'",value=f,fg=c.lava})end;return e end;function a.addTransferFields(g,b,c)local j=g:addList({x=2,y=2,width=53,height=24,scrollbar="hidden",items=a.getTransfers(b,c),background=c.bg})return j end;return a
